package com.fmrent.cars.model;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="cars") public class Car {
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,length=100) private String name; @Column(nullable=false,length=30) private String category; @Column(nullable=false,precision=10,scale=2) private BigDecimal price; @Column(nullable=false) private int seats; @Column(nullable=false,length=30) private String transmission; @Column(nullable=false,length=30) private String fuel; @Column(length=40) private String badge; @Column(nullable=false,length=500) private String imageUrl; @Column(nullable=false,length=100) private String imageFileId; @OneToMany(cascade=CascadeType.ALL,orphanRemoval=true) @JoinColumn(name="car_id",nullable=false) @OrderBy("displayOrder ASC") private java.util.List<CarImage> images=new java.util.ArrayList<>(); @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now();
 protected Car(){} public Car(String name,String category,BigDecimal price,int seats,String transmission,String fuel,String badge,String imageUrl,String imageFileId,java.util.List<CarImage> images){this.name=name;this.category=category;this.price=price;this.seats=seats;this.transmission=transmission;this.fuel=fuel;this.badge=badge;this.imageUrl=imageUrl;this.imageFileId=imageFileId;this.images.addAll(images);}
 public Long getId(){return id;} public String getName(){return name;} public String getCategory(){return category;} public BigDecimal getPrice(){return price;} public int getSeats(){return seats;} public String getTransmission(){return transmission;} public String getFuel(){return fuel;} public String getBadge(){return badge;} public String getImageUrl(){return imageUrl;} public String getImageFileId(){return imageFileId;} public java.util.List<CarImage> getImages(){return images;} public Instant getCreatedAt(){return createdAt;}
 public void updateDetails(String name,String category,BigDecimal price,int seats,String transmission,String fuel,String badge,String imageUrl,String imageFileId,java.util.List<CarImage> gallery){this.name=name;this.category=category;this.price=price;this.seats=seats;this.transmission=transmission;this.fuel=fuel;this.badge=badge;this.imageUrl=imageUrl;this.imageFileId=imageFileId;this.images.clear();this.images.addAll(gallery);}
}
